-- Follow-up Phase L server authority and resumable dataset inventory.
ALTER TABLE public.validation_runs ADD COLUMN IF NOT EXISTS progress_completed integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS exclusion_count integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS cancellation_requested_at timestamptz;
CREATE TABLE IF NOT EXISTS public.validation_datasets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source text NOT NULL CHECK(source IN ('MT5_HASHIBRIDGE','BINANCE','BYBIT','CSV')), status text NOT NULL CHECK(status IN ('DOWNLOADING','READY','FAILED','CANCELLED')), symbol text NOT NULL, timeframe text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, dataset_hash text NOT NULL, configuration_hash text, configuration_version text, provenance text NOT NULL, coverage jsonb NOT NULL DEFAULT '{}'::jsonb, resume_cursor timestamptz, created_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(), CHECK(starts_at<ends_at));
CREATE TABLE IF NOT EXISTS public.validation_dataset_candles (dataset_id uuid NOT NULL REFERENCES public.validation_datasets(id) ON DELETE RESTRICT, symbol text NOT NULL, market_type text NOT NULL, timeframe text NOT NULL, open_time timestamptz NOT NULL, open numeric NOT NULL, high numeric NOT NULL, low numeric NOT NULL, close numeric NOT NULL, volume numeric NOT NULL DEFAULT 0, source text NOT NULL, PRIMARY KEY(dataset_id,open_time), CHECK(high>=greatest(open,close,low)), CHECK(low<=least(open,close,high)));
CREATE TABLE IF NOT EXISTS public.mt5_scanner_feeds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), bridge_id text NOT NULL UNIQUE, feed_identity text NOT NULL UNIQUE, owner_controlled boolean NOT NULL DEFAULT true, execution_account_id uuid, enabled boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'CONFIGURATION_REQUIRED', last_heartbeat_at timestamptz, last_valid_candle_at timestamptz, validation_evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), CHECK(execution_account_id IS NULL));
ALTER TABLE public.validation_datasets ENABLE ROW LEVEL SECURITY;ALTER TABLE public.validation_dataset_candles ENABLE ROW LEVEL SECURITY;ALTER TABLE public.mt5_scanner_feeds ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admins read validation datasets" ON public.validation_datasets FOR SELECT TO authenticated USING(public.is_admin());CREATE POLICY "admins read validation candles" ON public.validation_dataset_candles FOR SELECT TO authenticated USING(public.is_admin());CREATE POLICY "admins read scanner feeds" ON public.mt5_scanner_feeds FOR SELECT TO authenticated USING(public.is_admin());
CREATE TRIGGER validation_dataset_candles_immutable BEFORE UPDATE OR DELETE ON public.validation_dataset_candles FOR EACH ROW EXECUTE FUNCTION public.reject_validation_immutable_update();
